package ir.fatahi.saherehplayer;

import android.app.*;
import android.content.*;
import android.media.*;
import android.media.session.*;
import android.net.Uri;
import android.os.*;
import android.support.v4.media.session.*;

public class MusicService extends Service {
    public static final String ACTION_PLAY="sp.PLAY", ACTION_TOGGLE="sp.TOGGLE", ACTION_NEXT="sp.NEXT", ACTION_PREV="sp.PREV", ACTION_STOP="sp.STOP", ACTION_SEEK="sp.SEEK", ACTION_VOLUME="sp.VOLUME", ACTION_TIMER="sp.TIMER";
    private MediaPlayer player; private MediaSession session; private android.media.audiofx.Equalizer equalizer; private android.media.audiofx.BassBoost bassBoost; private short bassStrength=300; private boolean autoNext=true, resumeAfterFocus=false, resumeOnFocus=true, pauseOnNoisy=true, crossfadeEnabled=false; private android.media.AudioManager audioManager; private android.media.AudioManager.OnAudioFocusChangeListener focusListener; private android.content.BroadcastReceiver noisyReceiver; private String title="ساهره پلیر", artist="فایل محلی", uri=""; private Handler handler=new Handler(Looper.getMainLooper()); private Runnable timerRunnable; private float volume=0.8f; private int positionBeforePause=0;
    @Override public void onCreate(){super.onCreate();createChannel();session=new MediaSession(this,"SaherehPlayer");session.setCallback(new MediaSession.Callback(){@Override public void onPlay(){resume();}@Override public void onPause(){pause();}@Override public void onSkipToNext(){next();}@Override public void onSkipToPrevious(){previous();}@Override public void onSeekTo(long p){seek((int)p);}});session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);session.setActive(true);audioManager=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);focusListener=change->{if(change==android.media.AudioManager.AUDIOFOCUS_GAIN){if(resumeAfterFocus){resumeAfterFocus=false;if(resumeOnFocus)resume();}}else if(change==android.media.AudioManager.AUDIOFOCUS_LOSS_TRANSIENT||change==android.media.AudioManager.AUDIOFOCUS_LOSS){resumeAfterFocus=player!=null&&player.isPlaying();pause();}};noisyReceiver=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){if(Intent.ACTION_AUDIO_BECOMING_NOISY.equals(i.getAction())&&pauseOnNoisy)pause();}};registerReceiver(noisyReceiver,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY));}
    @Override public int onStartCommand(Intent i,int flags,int startId){if(i==null)return START_STICKY;String a=i.getAction();if(ACTION_PLAY.equals(a)){uri=i.getStringExtra("uri");title=i.getStringExtra("title");artist=i.getStringExtra("artist");playUri();}else if(ACTION_TOGGLE.equals(a)){if(player!=null&&player.isPlaying())pause();else resume();}else if(ACTION_NEXT.equals(a))next();else if(ACTION_PREV.equals(a))previous();else if(ACTION_STOP.equals(a)){pause();stopForeground(false);}else if(ACTION_SEEK.equals(a))seek(i.getIntExtra("position",0));else if(ACTION_VOLUME.equals(a)){volume=i.getFloatExtra("volume",.8f);if(player!=null)player.setVolume(volume,volume);}else if("sp.BASS".equals(a)){bassStrength=(short)Math.max(0,Math.min(1000,i.getIntExtra("strength",300)));try{if(bassBoost!=null)bassBoost.setStrength(bassStrength);}catch(Exception ignored){}}else if(ACTION_TIMER.equals(a)){if(timerRunnable!=null)handler.removeCallbacks(timerRunnable);int m=i.getIntExtra("minutes",0);if(m>0){timerRunnable=()->{pause();stopForeground(false);};handler.postDelayed(timerRunnable,m*60000L);}}return START_STICKY;}
    private void playUri(){try{if(player!=null){player.reset();player.release();}player=new MediaPlayer();player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());if(audioManager!=null){int focus=audioManager.requestAudioFocus(focusListener,AudioManager.STREAM_MUSIC,AudioManager.AUDIOFOCUS_GAIN);if(focus!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){}}player.setDataSource(this,Uri.parse(uri));player.setVolume(crossfadeEnabled?0f:volume,crossfadeEnabled?0f:volume);player.setOnPreparedListener(mp->{try{if(equalizer!=null)equalizer.release();if(bassBoost!=null)bassBoost.release();equalizer=new android.media.audiofx.Equalizer(0,mp.getAudioSessionId());equalizer.setEnabled(true);bassBoost=new android.media.audiofx.BassBoost(0,mp.getAudioSessionId());bassBoost.setStrength(bassStrength);bassBoost.setEnabled(true);}catch(Exception ignored){}mp.start();if(crossfadeEnabled)rampIn(mp);updateSession();updateNotification();});player.setOnCompletionListener(mp->{if(autoNext){if(crossfadeEnabled)fadeOutThenNext();else next();}else pause();});player.setOnErrorListener((mp,w,e)->{stopForeground(false);return true;});player.prepareAsync();startForeground(41,notification());}catch(Exception e){stopForeground(true);}}
    private void resume(){if(player!=null){if(!player.isPlaying())player.start();updateSession();updateNotification();}}
    private void pause(){if(player!=null&&player.isPlaying()){player.pause();positionBeforePause=player.getCurrentPosition();}updateSession();updateNotification();}
    private void seek(int p){if(player!=null)try{player.seekTo(Math.max(0,Math.min(p,player.getDuration())));}catch(Exception ignored){}}
    private void rampIn(MediaPlayer mp){final long t=System.currentTimeMillis();Runnable[] r=new Runnable[1];r[0]=()->{if(player!=mp||!mp.isPlaying())return;float f=Math.min(1f,(System.currentTimeMillis()-t)/900f);try{mp.setVolume(volume*f,volume*f);}catch(Exception ignored){}if(f<1f)handler.postDelayed(r[0],80);};handler.post(r[0]);}
    private void fadeOutThenNext(){final MediaPlayer p=player;if(p==null){next();return;}final float start=volume;final long t=System.currentTimeMillis();Runnable[] r=new Runnable[1];r[0]=()->{if(player!=p)return;float f=1f-(System.currentTimeMillis()-t)/900f;if(f<=0){next();return;}try{p.setVolume(start*f,start*f);}catch(Exception ignored){}handler.postDelayed(r[0],80);};handler.post(r[0]);}
    private void next(){/* The UI owns the playlist; service stays available for notification transport. */ if(player!=null){player.seekTo(0);player.start();}}
    private void previous(){if(player!=null){if(player.getCurrentPosition()>3000)player.seekTo(0);else player.seekTo(0);}}
    public String currentUri(){return uri==null?"":uri;} public String currentTitle(){return title==null?"":title;} public String currentArtist(){return artist==null?"":artist;} public int currentPosition(){try{return player==null?0:player.getCurrentPosition();}catch(Exception e){return 0;}} public int currentDuration(){try{return player==null?0:Math.max(0,player.getDuration());}catch(Exception e){return 0;}} public boolean isPlaying(){return player!=null&&player.isPlaying();}
    private void updateSession(){if(session==null)return;long actions=PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS|PlaybackState.ACTION_SEEK_TO;int st=player!=null&&player.isPlaying()?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED;long pos=0;try{pos=player.getCurrentPosition();}catch(Exception ignored){}session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,title).putString(MediaMetadata.METADATA_KEY_ARTIST,artist).putLong(MediaMetadata.METADATA_KEY_DURATION,player==null?0:Math.max(0,player.getDuration())).build());session.setPlaybackState(new PlaybackState.Builder().setActions(actions).setState(st,pos,player!=null&&player.isPlaying()?1f:0f).build());}
    private void createChannel(){if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel("sahereh_music","پخش موسیقی",NotificationManager.IMPORTANCE_LOW);c.setDescription("کنترل پخش ساهره پلیر");((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c);}}
    private PendingIntent action(String a,int id){Intent i=new Intent(this,MusicActionReceiver.class).setAction(a);return PendingIntent.getBroadcast(this,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    private Notification notification(){Intent open=new Intent(this,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(this,1,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"sahereh_music"):new Notification.Builder(this);b.setContentTitle(title).setContentText(artist+" • ساهره پلیر").setSmallIcon(android.R.drawable.ic_media_play).setContentIntent(pi).setOngoing(player!=null&&player.isPlaying()).addAction(android.R.drawable.ic_media_previous,"قبلی",action(ACTION_PREV,2)).addAction(player!=null&&player.isPlaying()?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,"پخش/مکث",action(ACTION_TOGGLE,3)).addAction(android.R.drawable.ic_media_next,"بعدی",action(ACTION_NEXT,4));if(Build.VERSION.SDK_INT>=21)b.setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1,2));return b.build();}
    private void updateNotification(){try{((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(41,notification());}catch(Exception ignored){}}
    @Override public IBinder onBind(Intent i){return null;}
    @Override public void onDestroy(){if(timerRunnable!=null)handler.removeCallbacks(timerRunnable);try{if(noisyReceiver!=null)unregisterReceiver(noisyReceiver);if(audioManager!=null&&focusListener!=null)audioManager.abandonAudioFocus(focusListener);}catch(Exception ignored){}if(player!=null){player.release();player=null;}try{if(equalizer!=null)equalizer.release();if(bassBoost!=null)bassBoost.release();}catch(Exception ignored){}if(session!=null){session.setActive(false);session.release();}super.onDestroy();}
}